'use strict';
const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let config,cart=[],details={fulfillment:'pickup',area:'hall',deliveryMode:'address'},galleryIndex=0;
const cartDialog=$('#cart-dialog'),lightbox=$('#lightbox');
function toast(t){$('.toast').textContent=t;$('.toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('.toast').classList.remove('visible'),3000);}
function save(){try{localStorage.setItem('bierbach-selection-v1',JSON.stringify(cart));}catch{}updateCount();}
function updateCount(){$$('[data-cart-count]').forEach(el=>el.textContent=cart.reduce((s,x)=>s+x.quantity,0));}
function capture(){const f=$('#request-form');if(!f)return;const d=Object.fromEntries(new FormData(f));d.card=$('[name="card"]',f).checked;d.photoRequest=!!$('[name="photoRequest"]',f)?.checked;details={...details,...d};}
function field(label,name,opts={}){const {type='text',required=false,placeholder='',autocomplete='',max=160}=opts;return `<label>${label}<input name="${name}" type="${type}" value="${esc(details[name])}" ${required?'required':''} ${placeholder?`placeholder="${esc(placeholder)}"`:''} ${autocomplete?`autocomplete="${autocomplete}"`:''} maxlength="${max}"></label>`;}
function radio(name,value,label){return `<label class="choice ${details[name]===value?'selected':''}"><input type="radio" name="${name}" value="${value}" ${details[name]===value?'checked':''}><span>${label}</span></label>`;}
function renderCart(){
 if(!config)return;const root=$('#cart-content');if(!cart.length){root.innerHTML='<div class="empty-cart"><span aria-hidden="true">✳</span><h3>Hier ist Platz für Freude.</h3><p>Wählen Sie Ihre Blumenidee und stellen Sie eine persönliche Anfrage zusammen.</p><a class="button" href="floristik.html">Blumen entdecken ↗</a></div>';return;}
 root.innerHTML=`<div class="cart-note">Designkonzept · Ihre Auswahl ist eine unverbindliche Anfrage. Wunschbudgets sind keine bestätigten Produktpreise.</div><div class="cart-items">${cart.map((x,i)=>{const p=config.products.find(p=>p.id===x.id);return `<article class="cart-item"><img src="assets/${p.image}.webp" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>${Number.isInteger(p.priceCents)?'Preis':'Wunschbudget'}: ${CartCore.money(p.priceCents??x.budgetCents)} / Stück</p>${x.color?`<p class="small">${esc(x.color)}</p>`:''}<div class="quantity"><button type="button" data-qty="${i}" data-change="-1" aria-label="${esc(p.name)}: Menge verringern">−</button><span aria-label="Menge">${x.quantity}</span><button type="button" data-qty="${i}" data-change="1" aria-label="${esc(p.name)}: Menge erhöhen" ${x.quantity>=20?'disabled':''}>+</button><button type="button" class="remove-item" data-remove="${i}" aria-label="${esc(p.name)} entfernen">Entfernen</button></div></div></article>`;}).join('')}</div><button type="button" class="underlink clear-cart" id="clear-cart">Korb leeren</button>
 <form id="request-form"><fieldset><legend><span>01</span> Eine persönliche Note</legend><label class="check-row"><input name="card" type="checkbox" ${details.card?'checked':''}><span>Eine Grußkarte hinzufügen <strong>+ ${CartCore.money(config.cardCents)}</strong><small>Eine Karte für die gesamte Auswahl.</small></span></label><div data-show-card><label>Ihr Grußkartentext <span class="optional">optional</span><textarea name="cardText" rows="3" maxlength="500" placeholder="Ein paar liebe Worte …">${esc(details.cardText)}</textarea></label></div></fieldset>
 <fieldset><legend><span>02</span> Wie kommen die Blumen zu Ihnen?</legend><div class="choice-grid">${radio('fulfillment','pickup','Abholung <small>Bei uns in Gelbingen</small>')}${radio('fulfillment','delivery','Lieferung <small>Wir bringen die Freude</small>')}</div><div data-show-delivery><label>Liefergebiet<select name="area"><option value="hall" ${details.area==='hall'?'selected':''}>Schwäbisch Hall · ${CartCore.money(config.deliveryCents)}</option><option value="other" ${details.area==='other'?'selected':''}>Anderer Ort · Kosten auf Anfrage</option></select></label>
 <p class="form-section-label">Ein Zuhause. Oder ein Lieblingsplatz.</p><div class="choice-grid delivery-mode">${radio('deliveryMode','address','⌂ An eine Adresse <small>Haus, Büro oder Geschäft</small>')}${radio('deliveryMode','location','⌖ An einen Ort <small>Treffpunkt oder Kartenlink</small>')}</div>
 <div data-show-address>${field('Straße & Hausnummer <span class="optional">optional</span>','street',{autocomplete:'shipping street-address',placeholder:'z. B. Musterstraße 12'})}<div class="field-row">${field('Postleitzahl <span class="optional">optional</span>','zip',{autocomplete:'shipping postal-code',max:12})}${field('Ort <span class="optional">optional</span>','city',{autocomplete:'shipping address-level2',placeholder:'Schwäbisch Hall'})}</div></div>
 <div data-show-location>${field('Ort oder Treffpunkt <span class="optional">optional</span>','location',{placeholder:'z. B. Marktplatz, am Brunnen',max:300})}${field('Link zur Karte <span class="optional">optional</span>','mapLink',{type:'url',placeholder:'https://maps.google.com/…',max:1000})}<p class="small">Markierung in Ihrer Karten-App teilen und den Link hier einfügen. Oder den Ort einfach beschreiben.</p></div>
 <p class="small location-hint">Sie können den genauen Lieferort auch persönlich mit uns abstimmen. Alle Orts- und Adressfelder sind freiwillig.</p><div class="field-row">${field('Empfänger/in <span class="optional">optional</span>','recipient',{autocomplete:'shipping name'})}${field('Telefon Empfänger/in <span class="optional">optional</span>','recipientPhone',{type:'tel',autocomplete:'shipping tel'})}</div>${field('Lieferhinweis <span class="optional">optional</span>','deliveryNote',{placeholder:'z. B. Überraschung – bitte vorher mich anrufen',max:300})}</div>
 <label>Wunschdatum <span class="optional">optional · Bestätigung nach Absprache</span><input name="date" type="date" value="${esc(details.date)}" min="${localDate()}"></label></fieldset>
 <fieldset><legend><span>03</span> Wie erreichen wir Sie?</legend><div class="field-row">${field('Ihr Name','sender',{required:true,autocomplete:'billing name'})}${field('Telefon oder E-Mail','phone',{required:true,autocomplete:'billing tel'})}</div><label>Weitere Wünsche <span class="optional">optional</span><textarea name="notes" rows="2" maxlength="1000" placeholder="Anlass, Blumenwünsche oder etwas, das wir wissen sollten …">${esc(details.notes)}</textarea></label></fieldset>
 <div id="cart-totals" class="cart-totals" aria-live="polite"></div><p class="small">Blumen, Preis und Wunschtermin werden persönlich bestätigt. Es erfolgt keine Onlinezahlung.</p><button class="button full" type="submit">Anfrage ansehen <span>→</span></button><p class="small privacy-note">Adress- und Kontaktdaten bleiben bis zum Kopieren oder Teilen auf dieser Seite. <a href="datenschutz.html">Mehr zum Datenschutz</a>.</p></form>
 <section id="message-section" class="message-section" hidden><h3>Alles so, wie Sie es möchten?</h3><p>Prüfen Sie Ihre Anfrage. WhatsApp übernimmt den Text; Sie senden die Nachricht dort selbst ab.</p><label>Ihre vorbereitete Nachricht<textarea id="message-preview" rows="14" readonly></textarea></label><div class="message-buttons"><button type="button" class="button secondary" id="copy-message">Anfrage kopieren</button><a id="whatsapp-link" class="button whatsapp" hidden target="_blank" rel="noopener">In WhatsApp öffnen ↗</a></div><p id="whatsapp-note" class="small">WhatsApp wird nach Bestätigung der Geschäftsnummer freigeschaltet. Die vollständige Anfrage können Sie bereits kopieren.</p></section>`;
 $$('[data-qty]',root).forEach(b=>b.addEventListener('click',()=>{capture();const i=Number(b.dataset.qty);cart[i].quantity+=Number(b.dataset.change);if(cart[i].quantity<1)cart.splice(i,1);save();renderCart();}));
 $$('[data-remove]',root).forEach(b=>b.addEventListener('click',()=>{capture();cart.splice(Number(b.dataset.remove),1);save();renderCart();}));
 $('#clear-cart').addEventListener('click',()=>{cart=[];details={fulfillment:'pickup',area:'hall',deliveryMode:'address'};save();renderCart();});
 const form=$('#request-form');form.addEventListener('input',()=>{capture();updateFormState();$('#message-section').hidden=true;});form.addEventListener('change',()=>{capture();updateFormState();$('#message-section').hidden=true;});
 form.addEventListener('submit',e=>{e.preventDefault();capture();const date=$('[name="date"]');if(date.value&&date.value<localDate()){date.setCustomValidity('Bitte wählen Sie heute oder einen zukünftigen Termin.');date.reportValidity();return;}date.setCustomValidity('');const message=CartCore.message(cart,config,details);$('#message-preview').value=message;const enabled=typeof config.whatsappNumber==='string'&&/^\d{8,15}$/.test(config.whatsappNumber);const wa=$('#whatsapp-link');wa.hidden=!enabled;$('#whatsapp-note').textContent=enabled?'WhatsApp öffnet mit Ihrer Nachricht. Zum Versenden tippen Sie dort selbst auf Senden.':'WhatsApp wird nach Bestätigung der Geschäftsnummer freigeschaltet. Die vollständige Anfrage können Sie bereits kopieren.';if(enabled)wa.href='https://wa.me/'+config.whatsappNumber+'?text='+encodeURIComponent(message);$('#message-section').hidden=false;$('#message-section').scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'start'});});
 $('[name="date"]').addEventListener('input',e=>e.target.setCustomValidity(''));$('#copy-message').addEventListener('click',()=>copyText($('#message-preview').value,$('#message-preview')));updateFormState();
}
function updateFormState(){const f=$('#request-form');if(!f)return;const delivery=details.fulfillment==='delivery';$('[data-show-delivery]').hidden=!delivery;$('[data-show-card]').hidden=!details.card;$('[data-show-address]').hidden=details.deliveryMode!=='address';$('[data-show-location]').hidden=details.deliveryMode!=='location';$$('[data-show-delivery] input,[data-show-delivery] select').forEach(el=>el.disabled=!delivery);$$('[data-show-address] input').forEach(el=>el.disabled=!delivery||details.deliveryMode!=='address');$$('[data-show-location] input').forEach(el=>el.disabled=!delivery||details.deliveryMode!=='location');$('[name="cardText"]').disabled=!details.card;$$('.choice').forEach(el=>el.classList.toggle('selected',$('input',el).checked));const t=CartCore.totals(cart,config,details);$('#cart-totals').innerHTML=`<div><span>${t.hasBudget?'Blumen · Wunschbudgets':'Blumen'}</span><span>${CartCore.money(t.goods)}</span></div>${t.card?`<div><span>Grußkarte</span><span>${CartCore.money(t.card)}</span></div>`:''}${delivery?`<div><span>Lieferung ${details.area==='hall'?'Schwäbisch Hall':''}</span><span>${t.deliveryOnRequest?'Auf Anfrage':CartCore.money(t.delivery)}</span></div>`:'<div><span>Abholung</span><span>Ohne Lieferkosten</span></div>'}<div class="total"><span>${t.hasBudget?'Vorläufiger Budgetrahmen':'Vorläufige Summe'}</span><strong>${CartCore.money(t.total)}</strong></div>${t.deliveryOnRequest?'<p class="small">Zuzüglich Lieferkosten nach persönlicher Abstimmung.</p>':''}`;}
function localDate(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function reducedMotion(){return window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
async function copyText(text,textarea){try{await navigator.clipboard.writeText(text);toast('Anfrage kopiert.');}catch{if(textarea){textarea.focus();textarea.select();toast('Bitte den markierten Text kopieren.');}else{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();document.execCommand('copy');t.remove();toast('Anfrage kopiert.');}}}
function renderProducts(){const grid=$('[data-products]');if(!grid)return;const products=grid.dataset.products==='featured'?config.products.slice(0,3):config.products;grid.innerHTML=products.map(p=>`<article class="product-card reveal" data-category="${p.category}"><button class="product-photo" data-gallery="${p.id}" aria-label="${esc(p.name)}: Foto vergrößern"><img src="assets/${p.image}.webp" alt="${esc(p.name)} – Gestaltungsbeispiel von Blumen Bierbach" loading="lazy" width="800" height="900"><span>Foto ansehen ↗</span></button><div class="product-info"><div class="product-heading"><h3>${esc(p.name)}</h3><span>${p.priceCents?CartCore.money(p.priceCents):'Individuell'}</span></div><p>${esc(p.description)}</p><form class="product-form" data-product-id="${p.id}">${p.priceCents?`<p>Preis pro Strauß: ${CartCore.money(p.priceCents)}</p>`:`<label>Ihr Wunschbudget pro Strauß (€)<input name="budget" type="number" inputmode="decimal" min="1" max="10000" step="0.01" value="45" required aria-label="Wunschbudget für ${esc(p.name)}"><small>Frei wählbar · kein bestätigter Produktpreis</small></label>`}<label class="color-label">Farbwunsch <span class="optional">optional</span><input name="color" maxlength="120" placeholder="z. B. Rosé, Weiß & Grün" aria-label="Farbwunsch für ${esc(p.name)}"></label><button class="add-button" type="submit">In den Anfragekorb <span>+</span></button></form></div></article>`).join('');$$('.product-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const p=config.products.find(x=>x.id===f.dataset.productId),data=new FormData(f);const budgetCents=p.priceCents??Math.round(Number(data.get('budget'))*100);if(!Number.isSafeInteger(budgetCents)||budgetCents<1)return;const color=String(data.get('color')||'').trim();const existing=cart.find(x=>x.id===p.id&&x.budgetCents===budgetCents&&x.color===color);if(existing){if(existing.quantity>=20){toast('Maximal 20 Stück pro Auswahl.');return;}existing.quantity++;}else cart.push({id:p.id,budgetCents,color,quantity:1});save();toast(p.name+' ist im Anfragekorb.');}));$$('[data-gallery]').forEach(b=>b.addEventListener('click',()=>openGallery(config.products.findIndex(p=>p.id===b.dataset.gallery))));observeReveals();}
function openGallery(index){galleryIndex=index;renderGallery();if(!lightbox.open)lightbox.showModal();}
function renderGallery(){const p=config.products[galleryIndex];$('img',lightbox).src='assets/'+p.image+'.webp';$('img',lightbox).alt=p.name+' – Gestaltungsbeispiel';$('p',lightbox).textContent=p.name+' · '+(galleryIndex+1)+' / '+config.products.length;}
function observeReveals(){if(reducedMotion())return;const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target);}}),{threshold:.08});$$('.reveal:not(.is-visible)').forEach(el=>{el.classList.add('will-reveal');observer.observe(el);});}
$$('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$$('[data-cart-open]').forEach(b=>b.addEventListener('click',()=>{if(!config){toast('Der Anfragekorb wird geladen. Bitte versuchen Sie es gleich erneut.');return;}renderCart();cartDialog.showModal();}));
$('.menu-toggle').addEventListener('click',e=>{const expanded=e.currentTarget.getAttribute('aria-expanded')==='true';e.currentTarget.setAttribute('aria-expanded',String(!expanded));e.currentTarget.setAttribute('aria-label',expanded?'Menü öffnen':'Menü schließen');$('#navigation').classList.toggle('open',!expanded);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}if(lightbox.open&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){galleryIndex=(galleryIndex+(e.key==='ArrowLeft'?-1:1)+config.products.length)%config.products.length;renderGallery();}});
$('[data-gallery-prev]').addEventListener('click',()=>{galleryIndex=(galleryIndex-1+config.products.length)%config.products.length;renderGallery();});$('[data-gallery-next]').addEventListener('click',()=>{galleryIndex=(galleryIndex+1)%config.products.length;renderGallery();});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$$('[data-category]').forEach(el=>el.hidden=b.dataset.filter!=='all'&&el.dataset.category!==b.dataset.filter);observeReveals();}));
const contact=$('#contact-form');if(contact){const topic=new URLSearchParams(location.search).get('thema');if(topic&&[...contact.elements.topic.options].some(o=>o.value===topic))contact.elements.topic.value=topic;const contactText=()=>{const d=Object.fromEntries(new FormData(contact));return `Guten Tag, Blumen Bierbach!\n\n${d.message}\n\nThema: ${d.topic}\nName: ${d.name}\nE-Mail: ${d.email}`;};contact.addEventListener('submit',e=>{e.preventDefault();location.href='mailto:feedback@blumen-bierbach.de?subject='+encodeURIComponent(contact.elements.topic.value)+'&body='+encodeURIComponent(contactText());});$('#copy-contact').addEventListener('click',()=>{if(contact.reportValidity())copyText(contactText());});}
if(localDate()>'2026-10-18'){$$('[data-upcoming]').forEach(el=>el.hidden=true);$$('[data-no-events]').forEach(el=>el.hidden=false);}
observeReveals();
fetch('catalog.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json();}).then(data=>{config=data;try{cart=CartCore.sanitizeCart(JSON.parse(localStorage.getItem('bierbach-selection-v1')||'[]'),config.products);}catch{cart=[];}updateCount();renderProducts();}).catch(()=>{$$('[data-products]').forEach(el=>el.innerHTML='<p>Die Blumenauswahl konnte nicht geladen werden. Bitte laden Sie die Seite erneut oder kontaktieren Sie uns telefonisch.</p>');toast('Die Blumenauswahl konnte nicht geladen werden.');});
